
let data=[],index=0,selected='',playing=false,lastTick=0,acc=0,begin=null,end=null,map,own,track,markers,connection;
const $=id=>document.getElementById(id),taipei=s=>new Date(s).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false});
function visible(t){return t[4]<=Number($('radius').value)&&t[5]<=Number($('age').value)&&t[0]!==$('exclude').value.trim()&&(!trimSearch()||(t[0]+' '+t[1]).toLowerCase().includes(trimSearch()))}function trimSearch(){return $('search').value.trim().toLowerCase()}
function rebuildTrack(){if(!track)return;let chunks=[],chunk=[],last=null;for(let s of AnalysisTools.samples()){let p=ownAt(s);if(!p||p.breakBefore||last!==null&&s.pts-last>Math.max(2,activeProject?.meta?.step||1)*1.5){if(chunk.length)chunks.push(chunk);chunk=[]}if(p)chunk.push([p.lat,p.lon]);last=s.pts}if(chunk.length)chunks.push(chunk);track.setLatLngs(chunks);AnalysisTools.points()}
function initMap(){if(!window.L){$('error').textContent='地圖套件無法載入，請確認網路後重新整理。';return}let first=data.find(s=>s.lat!==null&&s.lon!==null);map=L.map('map').setView(first?[first.lat,first.lon]:[22.62,120.28],15);setupFusionMap();track=L.polyline([],{color:'#159d94',weight:3,opacity:.55}).addTo(map);own=L.marker(first?[first.lat,first.lon]:[22.62,120.28],{icon:L.divIcon({className:'dot',iconSize:[14,14]})}).addTo(map).bindTooltip('本船 · 插值位置');markers=L.layerGroup().addTo(map);connection=L.layerGroup().addTo(map);rebuildTrack();if(track.getBounds().isValid())map.fitBounds(track.getBounds().pad(.2))}
